/* Abstract motion specimens: duration and easing are compared independently. */
function motionLab(){
 const durations=[['Feedback',180,'Button states, selection and immediate feedback.'],['Transition',280,'Menus, panels and changes between views.'],['Expression',800,'Occasional brand moments and larger compositions.']];
 const curves=[['Standard','.22,1,.36,1','M8 92 C26 8 38 8 92 8','Move between two visible states.'],['Enter','0,0,.2,1','M8 92 C8 92 25 8 92 8','Arrive quickly, then settle into place.'],['Exit','.4,0,1,1','M8 92 C42 92 92 8 92 8','Accelerate away as an element leaves.']];
 return `<section class="motion-lab"><div class="motion-lab-heading"><div><span class="meta">Motion, made visible</span><h2>See the pace.<br>Feel the curve.</h2><p>Same distance. Different timing. A clear language for how things move.</p></div><div class="motion-lab-controls"><button data-motion-pause aria-pressed="false">Pause demos</button><button data-motion-replay>Replay</button><label>Playback <select data-motion-rate><option value="1">Actual speed · 1×</option><option value="0.25">Slow study · ¼×</option></select></label></div></div><div class="motion-lab-label"><h3>Duration</h3><span>Same easing · cubic-bezier(.22, 1, .36, 1)</span></div><div class="motion-duration-grid">${durations.map(([name,ms,use],i)=>`<article class="motion-specimen tone-${i}"><div class="motion-specimen-title"><h4>${name}</h4><code>${ms} ms</code></div><div class="motion-runway" data-motion-duration="${ms}" data-motion-easing="cubic-bezier(.22,1,.36,1)" aria-label="${name}: ball travels from start to finish in ${ms} milliseconds"><span class="motion-track-line"></span><i class="motion-endpoint start"></i><i class="motion-endpoint end"></i><div class="motion-ball"></div><div class="motion-track-labels"><span>Start</span><span>Finish</span></div></div><p>${use}</p><code class="motion-token">motion.duration.${name.toLowerCase()}</code></article>`).join('')}</div><div class="motion-lab-label"><h3>Easing</h3><span>Same duration · 280 ms</span></div><div class="motion-easing-list">${curves.map(([name,curve,path,use])=>`<article class="motion-easing-row"><div class="motion-easing-caption"><h4>${name}</h4><p>${use}</p><code>cubic-bezier(${curve})</code></div><svg class="motion-curve-chart" viewBox="0 0 100 100" role="img" aria-label="${name} easing curve: progress over time"><path class="curve-grid" d="M8 8V92H92 M8 50H92 M50 8V92"/><path class="curve-reference" d="M8 92 92 8"/><path class="curve-line" d="${path}"/><circle cx="8" cy="92" r="3"/><circle cx="92" cy="8" r="3"/></svg><div class="motion-runway" data-motion-duration="280" data-motion-easing="cubic-bezier(${curve})" aria-label="${name} easing ball demonstration at 280 milliseconds"><span class="motion-track-line"></span><i class="motion-endpoint start"></i><i class="motion-endpoint end"></i><div class="motion-ball"></div><div class="motion-track-labels"><span>0%</span><span>100%</span></div></div></article>`).join('')}</div><div class="motion-lab-foot"><p>Each demo holds briefly at the start and finish so you can compare the movement. Playback speed changes the preview only.</p><span data-motion-state role="status">Playing at actual speed</span></div></section>`;
}
function bindMotionLab(root){const lab=root.querySelector('.motion-lab');if(!lab)return()=>{};const media=matchMedia('(prefers-reduced-motion: reduce)'),reduced=media.matches||root.classList.contains('motion-reduced')||document.body.classList.contains('motion-reduced')||document.documentElement.classList.contains('motion-reduced');let paused=reduced,rate=1,animations=[];const pause=lab.querySelector('[data-motion-pause]'),status=lab.querySelector('[data-motion-state]');function sync(){pause.textContent=paused?'Play demos':'Pause demos';pause.setAttribute('aria-pressed',String(paused));status.textContent=paused?(reduced?'Paused · reduced motion':'Paused'):(rate===1?'Playing at actual speed':'Playing at quarter speed · preview only')}function build(){animations.forEach(a=>a.cancel());animations=[];lab.querySelectorAll('.motion-runway').forEach(track=>{const ball=track.querySelector('.motion-ball'),distance=Math.max(0,track.clientWidth-80),ms=+track.dataset.motionDuration,total=ms+1500,start=600/total,end=(600+ms)/total;const a=ball.animate([{transform:'translateX(0)',offset:0},{transform:'translateX(0)',offset:start,easing:track.dataset.motionEasing},{transform:`translateX(${distance}px)`,offset:end},{transform:`translateX(${distance}px)`,offset:1}],{duration:total,iterations:Infinity,fill:'both'});a.playbackRate=rate;if(paused)a.pause();animations.push(a)});sync()}pause.onclick=()=>{paused=!paused;animations.forEach(a=>paused?a.pause():a.play());sync()};lab.querySelector('[data-motion-replay]').onclick=()=>{animations.forEach(a=>{a.currentTime=0;if(!paused)a.play()})};lab.querySelector('[data-motion-rate]').onchange=e=>{rate=Number(e.target.value);animations.forEach(a=>a.updatePlaybackRate(rate));sync()};const observer=new ResizeObserver(build);observer.observe(lab);build();return()=>{observer.disconnect();animations.forEach(a=>a.cancel())}}
